    //var fileName = "excelData.xls";
    var fileName = "excelData.xlsx";
    var options = {
        fileName: fileName,
        type: "1",
        startRowIndex: "3",
        "title": "aaaa",
        maxRowCount: "7000"
    };
    var infoArr = [];
    var infoObj = {
        bgColor: "",
        borderColor: "",
        borderWidth: "",
        colIndex: 1,
        colSpan: 2,
        color: "",
        drawBorder: "false",
        fontName: "굴림",
        fontSize: 15,
        fontWeight: "bold",
        rowIndex: 1,
        rowSpan: 1,
        text: "TITLE",
        textAlign: "center",
        wordWrap: "true"
    };
    infoArr.push(infoObj);
    grd2.advancedExcelDownload(options, infoArr); // .xlsx 일경우 100건 이상일 경우 오류 발생
};
scwin.btnExcelUp_onclick = function(e) {
    var options = {
        type: "1",
        startRowIndex: 1
    };
    grd3.advancedExcelUpload(options);
};
scwin.trigger1_onclick = function(e) {
    grd3.advancedExcelDownload({
        type: "1"
    })
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
